def countSpecialIntegers(nums):
    # Map each value to the sorted list of indices where it occurs
    positions = {}
    for i, x in enumerate(nums):
        positions.setdefault(x, []).append(i)

    count = 0
    for idxs in positions.values():
        # Need at least three occurrences
        if len(idxs) < 3:
            continue
        # All consecutive gaps must equal the first gap
        gap = idxs[1] - idxs[0]
        ok = True
        for j in range(2, len(idxs)):
            if idxs[j] - idxs[j - 1] != gap:
                ok = False
                break
        if ok:
            count += 1
    return count
